class Solution  {
    private boolean letter(char c) {
        return c>='a'&&c<='z'||c>='A'&&c<='Z';
    }
    public String mirrorLetters(String text) {
        char[] a=text.toCharArray();
        int l=0,r=a.length-1;
        while(l<r) {
            if(!letter(a[l]))l++;
            else if(!letter(a[r]))r--;
            else {
                char t=a[l];
                a[l++]=a[r];
                a[r--]=t;
            }
        }
        return new String(a);
    }
}

class Solution:
    def mirrorLetters(self, text: str) -> str:
        chars = list(text)
        left, right = 0, len(chars) - 1
        def letter(char):
            return "A" <= char <= "Z" or "a" <= char <= "z"
        while left < right:
            if not letter(chars[left]):
                left += 1
            elif not letter(chars[right]):
                right -= 1
            else:
                chars[left], chars[right] = chars[right], chars[left]
                left += 1
                right -= 1
        return "".join(chars)

class Solution  {
    mirrorLetters(text:string):string {
        const a=Array.from(text);
        const letter=(c:string)=>/^[a-zA-Z]$/.test(c);
        let l=0,r=a.length-1;
        while(l<r) {
            if(!letter(a[l]))l++;
            else if(!letter(a[r]))r--;
            else {
                [a[l],a[r]]=[a[r],a[l]];
                l++;
                r--;
            }
        }
        return a.join('');
    }
}
